// createThroughCore is CreateOne on the repository's transaction: input's row
// stamped, created by the behaviors' core, whose uses initialize the fields
// they own, with the columns the insert writes, and read back.
func (r *AccountRepository) createThroughCore(ctx context.Context, input *AccountCreate) (*types.Account, error) {
	row := input.row()
	columns, err := r.createColumns(row)
	if err != nil {
		return nil, err
	}
	opts := &rules.CreateOptions{ID: r.createKey(row), ExecuteOptions: rules.ExecuteOptions{OwnColumns: columns}}
	key, err := rules.RunCreate(ctx, rulesHost(r.tx), "Account", r.coreOwn(row), behaviorCaller(ctx), opts)
	if err != nil {
		return nil, err
	}
	id, err := types.ParseIdentityUUID(key)
	if err != nil {
		return nil, fmt.Errorf("create Account: the core's key %q: %w", key, err)
	}
	return r.GetOne(ctx, id, nil)
}

// upsertInputs are inputs as an upsert inserts them (D103): each one's row
// with the fields its behaviors own as the core's create of it gives them,
// run to its change set and not applied, so the insert writes what CreateOne
// would have, and the update, which sets none of them, leaves them as the
// row holds them. A refusal of the core's is returned before anything is
// written.
func (r *AccountRepository) upsertInputs(ctx context.Context, inputs []*AccountCreate) ([]*types.Account, error) {
	host := rulesHost(r.tx)
	rows := make([]*types.Account, 0, len(inputs))
	for _, input := range inputs {
		row := input.row()
		owned, err := rules.PrepareCreate(ctx, host, "Account", r.coreOwn(row), behaviorCaller(ctx), &rules.CreateOptions{ID: r.createKey(row)})
		if err != nil {
			return nil, err
		}
		if value, ok := owned["Pool"]["availability"]; ok {
			if err := json.Unmarshal(value, &row.PoolAvailability); err != nil {
				return nil, fmt.Errorf("upsert Account: the core's Pool.availability %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["Pool"]["outUntil"]); err != nil {
			return nil, fmt.Errorf("upsert Account: the core's Pool.outUntil: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.PoolOutUntil = &value
		}
		if value, ok := owned["Pool"]["outReason"]; ok {
			if err := json.Unmarshal(value, &row.PoolOutReason); err != nil {
				return nil, fmt.Errorf("upsert Account: the core's Pool.outReason %s: %w", value, err)
			}
		}
		if at, err := rules.TimeOfMillis(owned["Pool"]["checkedAt"]); err != nil {
			return nil, fmt.Errorf("upsert Account: the core's Pool.checkedAt: %w", err)
		} else if at != nil {
			value := types.TemporalDateTime(*at)
			row.PoolCheckedAt = &value
		}
		rows = append(rows, row)
	}
	return rows, nil
}

// Allowed fields for Account (for validation and ordering)
var AccountAllowedFields = map[string]bool{
	"id":                true,
	"owner":             true,
	"name":              true,
	"vendor":            true,
	"kind":              true,
	"rank":              true,
	"pool_availability": true,
	"pool_out_until":    true,
	"pool_out_reason":   true,
	"pool_checked_at":   true,
	"_version":          true,
}

// Quoted field names for Account (for SQL generation)
var AccountQuotedFields = map[string]string{
	"id":                `id`,
	"owner":             `"owner"`,
	"name":              `"name"`,
	"vendor":            `vendor`,
	"kind":              `kind`,
	"rank":              `rank`,
	"pool_availability": `pool_availability`,
	"pool_out_until":    `pool_out_until`,
	"pool_out_reason":   `pool_out_reason`,
	"pool_checked_at":   `pool_checked_at`,
	"_version":          `_version`,
}

// accountSortColumns are the columns of Account's sort fields, by
// field, as FindPage's ORDER BY and keyset write them: qualified by the table,
// and by page_key, the alias of the subquery that reads the key's row. They
// are the only text of a sort that reaches its SQL (D60, amended).
var accountSortColumns = map[AccountSortField]struct{ sql, key string }{
	AccountSortById:     {`account.id`, `page_key.id`},
	AccountSortByOwner:  {`account."owner"`, `page_key."owner"`},
	AccountSortByName:   {`account."name"`, `page_key."name"`},
	AccountSortByVendor: {`account.vendor`, `page_key.vendor`},
	AccountSortByRank:   {`account.rank`, `page_key.rank`},
}

// buildAccountOrderByClause builds an ORDER BY clause for Account.
// quotedTable is the table's name as the FROM clause spells it, quoted when
// it is a keyword (a table named order is "order").
func buildAccountOrderByClause(orderBy []AccountOrderBy, quotedTable string) string {
	if len(orderBy) == 0 {
		return ""
	}

	var clauses []string
	for _, order := range orderBy {
		fieldStr := string(order.Field)
		direction := "ASC"
		if order.Desc {
			direction = "DESC"
		}
		// Use pre-computed quoted field name
		quotedField, ok := AccountQuotedFields[fieldStr]
		if !ok {
			quotedField = fieldStr // Fallback to unquoted if not found
		}
		clauses = append(clauses, fmt.Sprintf("%s.%s %s", quotedTable, quotedField, direction))
	}

	if len(clauses) == 0 {
		return ""
	}

	return " ORDER BY " + strings.Join(clauses, ", ")
}

func accountUUIDValue(value any) (types.IdentityUUID, bool) {
	switch v := value.(type) {
	case types.IdentityUUID:
		return v, true
	case *types.IdentityUUID:
		if v == nil {
			var zero types.IdentityUUID
			return zero, false
		}
		return *v, true
	default:
		var zero types.IdentityUUID
		return zero, false
	}
}

func accountUUIDPtr(value types.IdentityUUID) *types.IdentityUUID {
	return &value
}

// GetOne retrieves a single Account by ID
func (r *AccountRepository) GetOne(ctx context.Context, id types.IdentityUUID, opts *AccountGetOptions) (*types.Account, error) {
	// Determine if we're using partial field selection
	var fieldStrings []string
	usePartialFields := opts != nil && !opts.Fields.IsZero()

	// Build query - if no fields specified, select all in scan order
	var query string
	if usePartialFields {
		// Build selected fields in OrderedMembers order so FK columns match scan order.
		if opts.Fields.Id {
			fieldStrings = append(fieldStrings, "id")
		}
		if opts.Fields.Owner {
			fieldStrings = append(fieldStrings, "owner")
		}
		if opts.Fields.Name {
			fieldStrings = append(fieldStrings, "name")
		}
		if opts.Fields.Vendor {
			fieldStrings = append(fieldStrings, "vendor")
		}
		if opts.Fields.Kind {
			fieldStrings = append(fieldStrings, "kind")
		}
		if opts.Fields.Rank {
			fieldStrings = append(fieldStrings, "rank")
		}
		if opts.Fields.PoolAvailability {
			fieldStrings = append(fieldStrings, "pool_availability")
		}
		if opts.Fields.PoolOutUntil {
			fieldStrings = append(fieldStrings, "pool_out_until")
		}
		if opts.Fields.PoolOutReason {
			fieldStrings = append(fieldStrings, "pool_out_reason")
		}
		if opts.Fields.PoolCheckedAt {
			fieldStrings = append(fieldStrings, "pool_checked_at")
		}
		if opts.Fields.Version {
			fieldStrings = append(fieldStrings, "_version")
		}
		// Validate fields
		if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
			return nil, err
		}
		selectFields := buildSelectFieldsTyped(fieldStrings, "account")
		query = fmt.Sprintf(`SELECT %s FROM account WHERE id = $1`, selectFields)
	} else {
		// Select all fields in explicit order matching scan order (using OrderedMembers for schema order)
		query = `SELECT "id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version" FROM account WHERE id = $1`
	}

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}

	// Scan result - when selecting all fields, scan directly into struct
	result := &types.Account{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempPoolAvailability sql.NullString
	var tempPoolOutUntil *types.TemporalDateTime
	var tempPoolOutReason sql.NullString
	var tempPoolCheckedAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	var err error
	if usePartialFields {
		// Dynamic scanning for partial field selection
		// Track whether special fields were selected so we can post-process after Scan.

		var selectedPoolAvailability bool
		var selectedPoolOutUntil bool
		var selectedPoolOutReason bool
		var selectedPoolCheckedAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "owner":
				scanDest[i] = &result.Owner
			case "name":
				scanDest[i] = &result.Name
			case "vendor":
				scanDest[i] = &result.Vendor
			case "kind":
				scanDest[i] = &result.Kind
			case "rank":
				scanDest[i] = &result.Rank
			case "pool_availability":
				scanDest[i] = &tempPoolAvailability
				selectedPoolAvailability = true
			case "pool_out_until":
				scanDest[i] = &tempPoolOutUntil
				selectedPoolOutUntil = true
			case "pool_out_reason":
				scanDest[i] = &tempPoolOutReason
				selectedPoolOutReason = true
			case "pool_checked_at":
				scanDest[i] = &tempPoolCheckedAt
				selectedPoolCheckedAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Account.GetOne", fieldName)
			}
		}

		err = row.Scan(scanDest...)
		if err == nil {
			// Copy nullable fields when present
			var jsonFieldDecodeErr error

			if selectedPoolAvailability && tempPoolAvailability.Valid {
				result.PoolAvailability = tempPoolAvailability.String
			}
			if selectedPoolOutUntil && tempPoolOutUntil != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolOutUntil = tempPoolOutUntil
			}
			if selectedPoolOutReason && tempPoolOutReason.Valid {
				result.PoolOutReason = tempPoolOutReason.String
			}
			if selectedPoolCheckedAt && tempPoolCheckedAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolCheckedAt = tempPoolCheckedAt
			}
			if jsonFieldDecodeErr != nil {
				return nil, jsonFieldDecodeErr
			}
		}
	} else {

		// Scan all fields in schema order (matches DDL column order)
		err = row.Scan(

			&result.Id,

			&result.Owner,

			&result.Name,

			&result.Vendor,

			&result.Kind,

			&result.Rank,

			&tempPoolAvailability,

			&tempPoolOutUntil,

			&tempPoolOutReason,

			&tempPoolCheckedAt,

			&result.Version,
		)

		if err == nil {
			// Copy nullable fields when present

			if tempPoolAvailability.Valid {
				result.PoolAvailability = tempPoolAvailability.String
			}
			if tempPoolOutUntil != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolOutUntil = tempPoolOutUntil
			}
			if tempPoolOutReason.Valid {
				result.PoolOutReason = tempPoolOutReason.String
			}
			if tempPoolCheckedAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolCheckedAt = tempPoolCheckedAt
			}
		}
	}

	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan row: %w", err)
	}

	// Hydrate relationship foreign keys into nested objects from typed field selections.

	return result, nil
}

// GetManyByIDs retrieves multiple Account records by their IDs in a single query
func (r *AccountRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Account, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Account{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version" FROM account WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Account, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Account{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempPoolAvailability sql.NullString
		var tempPoolOutUntil *types.TemporalDateTime
		var tempPoolOutReason sql.NullString
		var tempPoolCheckedAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Owner,

			&entity.Name,

			&entity.Vendor,

			&entity.Kind,

			&entity.Rank,

			&tempPoolAvailability,

			&tempPoolOutUntil,

			&tempPoolOutReason,

			&tempPoolCheckedAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempPoolAvailability.Valid {
			entity.PoolAvailability = tempPoolAvailability.String
		}
		if tempPoolOutUntil != nil {
			entity.PoolOutUntil = tempPoolOutUntil
		}
		if tempPoolOutReason.Valid {
			entity.PoolOutReason = tempPoolOutReason.String
		}
		if tempPoolCheckedAt != nil {
			entity.PoolCheckedAt = tempPoolCheckedAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := accountUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

// FindOne retrieves the first Account matching the filter
func (r *AccountRepository) FindOne(ctx context.Context, filter *AccountFilter, opts *AccountFindOptions) (*types.Account, error) {
	// Determine if we're using partial field selection
	var fieldStrings []string
	var selectFields string
	usePartialFields := opts != nil && !opts.Fields.IsZero()

	if usePartialFields {
		// Build selected fields in OrderedMembers order so FK columns match scan order.
		if opts.Fields.Id {
			fieldStrings = append(fieldStrings, "id")
		}
		if opts.Fields.Owner {
			fieldStrings = append(fieldStrings, "owner")
		}
		if opts.Fields.Name {
			fieldStrings = append(fieldStrings, "name")
		}
		if opts.Fields.Vendor {
			fieldStrings = append(fieldStrings, "vendor")
		}
		if opts.Fields.Kind {
			fieldStrings = append(fieldStrings, "kind")
		}
		if opts.Fields.Rank {
			fieldStrings = append(fieldStrings, "rank")
		}
		if opts.Fields.PoolAvailability {
			fieldStrings = append(fieldStrings, "pool_availability")
		}
		if opts.Fields.PoolOutUntil {
			fieldStrings = append(fieldStrings, "pool_out_until")
		}
		if opts.Fields.PoolOutReason {
			fieldStrings = append(fieldStrings, "pool_out_reason")
		}
		if opts.Fields.PoolCheckedAt {
			fieldStrings = append(fieldStrings, "pool_checked_at")
		}
		if opts.Fields.Version {
			fieldStrings = append(fieldStrings, "_version")
		}
		// Validate fields
		if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
			return nil, err
		}
		selectFields = buildSelectFieldsTyped(fieldStrings, "account")
	} else {
		// Select all fields in explicit order matching scan order (using OrderedMembers for schema order)
		selectFields = `"id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version"`
		if opts == nil {
			opts = &AccountFindOptions{}
		}
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildAccountOrderByClause(opts.OrderBy, `account`)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM account%s%s LIMIT 1`, selectFields, whereClause, orderByClause)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, args...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, args...)
	}

	// Scan result
	result := &types.Account{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempPoolAvailability sql.NullString
	var tempPoolOutUntil *types.TemporalDateTime
	var tempPoolOutReason sql.NullString
	var tempPoolCheckedAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	var err error
	if usePartialFields {
		// Dynamic scanning for partial field selection
		// Track whether special fields were selected so we can post-process after Scan.

		var selectedPoolAvailability bool
		var selectedPoolOutUntil bool
		var selectedPoolOutReason bool
		var selectedPoolCheckedAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "owner":
				scanDest[i] = &result.Owner
			case "name":
				scanDest[i] = &result.Name
			case "vendor":
				scanDest[i] = &result.Vendor
			case "kind":
				scanDest[i] = &result.Kind
			case "rank":
				scanDest[i] = &result.Rank
			case "pool_availability":
				scanDest[i] = &tempPoolAvailability
				selectedPoolAvailability = true
			case "pool_out_until":
				scanDest[i] = &tempPoolOutUntil
				selectedPoolOutUntil = true
			case "pool_out_reason":
				scanDest[i] = &tempPoolOutReason
				selectedPoolOutReason = true
			case "pool_checked_at":
				scanDest[i] = &tempPoolCheckedAt
				selectedPoolCheckedAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Account.FindOne", fieldName)
			}
		}

		err = row.Scan(scanDest...)
		if err == nil {
			// Copy nullable fields when present
			var jsonFieldDecodeErr error

			if selectedPoolAvailability && tempPoolAvailability.Valid {
				result.PoolAvailability = tempPoolAvailability.String
			}
			if selectedPoolOutUntil && tempPoolOutUntil != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolOutUntil = tempPoolOutUntil
			}
			if selectedPoolOutReason && tempPoolOutReason.Valid {
				result.PoolOutReason = tempPoolOutReason.String
			}
			if selectedPoolCheckedAt && tempPoolCheckedAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolCheckedAt = tempPoolCheckedAt
			}
			if jsonFieldDecodeErr != nil {
				return nil, jsonFieldDecodeErr
			}

			// Set relationship IDs from scanned FK values
		}
	} else {
		// Scan all fields in schema order (matches DDL column order)
		err = row.Scan(

			&result.Id,

			&result.Owner,

			&result.Name,

			&result.Vendor,

			&result.Kind,

			&result.Rank,

			&tempPoolAvailability,

			&tempPoolOutUntil,

			&tempPoolOutReason,

			&tempPoolCheckedAt,

			&result.Version,
		)

		if err == nil {
			// Copy nullable fields when present

			if tempPoolAvailability.Valid {
				result.PoolAvailability = tempPoolAvailability.String
			}
			if tempPoolOutUntil != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolOutUntil = tempPoolOutUntil
			}
			if tempPoolOutReason.Valid {
				result.PoolOutReason = tempPoolOutReason.String
			}
			if tempPoolCheckedAt != nil {
				// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
				result.PoolCheckedAt = tempPoolCheckedAt
			}
		}
	}

	if err != nil {
		if err == pgx.ErrNoRows {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan row: %w", err)
	}

	// Hydrate relationship foreign keys into nested objects from typed field selections.

	return result, nil
}

// FindMany retrieves multiple Account records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *AccountRepository) FindMany(ctx context.Context, filter *AccountFilter, opts *AccountFindOptions) ([]*types.Account, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}

	// Build selected fields in OrderedMembers order so FK columns match scan order.
	fieldStrings := accountFieldStrings(opts.Fields)

	// Validate fields
	if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
		return nil, 0, err
	}

	// Build SELECT clause
	selectFields := buildSelectFieldsTyped(fieldStrings, "account")
	if selectFields == "" {
		return nil, 0, fmt.Errorf("no valid fields specified")
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildAccountOrderByClause(opts.OrderBy, `account`)

	// Build LIMIT/OFFSET clause
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM account%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)

	// Get total count, unless the options skip it (D89)
	totalCount := -1
	if !opts.SkipCount {
		countQuery := fmt.Sprintf(`SELECT COUNT(*) FROM account%s`, whereClause)

		var countRow pgx.Row
		if r.tx != nil {
			countRow = r.tx.QueryRow(ctx, countQuery, args...)
		} else {
			countRow = r.db.pool.QueryRow(ctx, countQuery, args...)
		}
		if err := countRow.Scan(&totalCount); err != nil {
			return nil, 0, fmt.Errorf("failed to get count: %w", err)
		}
	}

	results, err := r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, 0, err
	}
	return results, totalCount, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for the rows of another
// table's read (D90), which counts nothing, as the TypeScript
// repositories' include does.
func (r *AccountRepository) findRelated(ctx context.Context, filter *AccountFilter, opts *AccountFindOptions) ([]*types.Account, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	fieldStrings := accountFieldStrings(opts.Fields)
	if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "account")
	if selectFields == "" {
		return nil, fmt.Errorf("no valid fields specified")
	}
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)
	orderByClause := buildAccountOrderByClause(opts.OrderBy, `account`)
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)
	query := fmt.Sprintf(`SELECT %s FROM account%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)
	return r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
}

// accountFieldStrings are the columns fields selects, in OrderedMembers
// order so FK columns match scan order, and the primary key when fields
// hydrates a hasMany relation, which maps the children by it.
func accountFieldStrings(fields AccountFields) []string {
	var fieldStrings []string
	if fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if fields.Owner {
		fieldStrings = append(fieldStrings, "owner")
	}
	if fields.Name {
		fieldStrings = append(fieldStrings, "name")
	}
	if fields.Vendor {
		fieldStrings = append(fieldStrings, "vendor")
	}
	if fields.Kind {
		fieldStrings = append(fieldStrings, "kind")
	}
	if fields.Rank {
		fieldStrings = append(fieldStrings, "rank")
	}
	if fields.PoolAvailability {
		fieldStrings = append(fieldStrings, "pool_availability")
	}
	if fields.PoolOutUntil {
		fieldStrings = append(fieldStrings, "pool_out_until")
	}
	if fields.PoolOutReason {
		fieldStrings = append(fieldStrings, "pool_out_reason")
	}
	if fields.PoolCheckedAt {
		fieldStrings = append(fieldStrings, "pool_checked_at")
	}
	if fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	return fieldStrings
}

// findRows runs query, a select of the columns fieldStrings names, in turn,
// with args, scans its rows, and hydrates the relations fields selects, as
// FindMany and FindPage read them. method names the caller in an error.
func (r *AccountRepository) findRows(ctx context.Context, method, query string, args []interface{}, fieldStrings []string, fields AccountFields) ([]*types.Account, error) {
	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Account{}
	for rows.Next() {
		result := &types.Account{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempPoolAvailability sql.NullString
		var tempPoolOutUntil *types.TemporalDateTime
		var tempPoolOutReason sql.NullString
		var tempPoolCheckedAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)

		// Track whether special fields were selected so we can post-process after Scan.

		var selectedPoolAvailability bool
		var selectedPoolOutUntil bool
		var selectedPoolOutReason bool
		var selectedPoolCheckedAt bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "owner":
				scanDest[i] = &result.Owner
			case "name":
				scanDest[i] = &result.Name
			case "vendor":
				scanDest[i] = &result.Vendor
			case "kind":
				scanDest[i] = &result.Kind
			case "rank":
				scanDest[i] = &result.Rank
			case "pool_availability":
				scanDest[i] = &tempPoolAvailability
				selectedPoolAvailability = true
			case "pool_out_until":
				scanDest[i] = &tempPoolOutUntil
				selectedPoolOutUntil = true
			case "pool_out_reason":
				scanDest[i] = &tempPoolOutReason
				selectedPoolOutReason = true
			case "pool_checked_at":
				scanDest[i] = &tempPoolCheckedAt
				selectedPoolCheckedAt = true
			case "_version":
				scanDest[i] = &result.Version
			default:
				return nil, fmt.Errorf("unexpected field %q for Account.%s", fieldName, method)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present
		var jsonFieldDecodeErr error

		if selectedPoolAvailability && tempPoolAvailability.Valid {
			result.PoolAvailability = tempPoolAvailability.String
		}
		if selectedPoolOutUntil && tempPoolOutUntil != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.PoolOutUntil = tempPoolOutUntil
		}
		if selectedPoolOutReason && tempPoolOutReason.Valid {
			result.PoolOutReason = tempPoolOutReason.String
		}
		if selectedPoolCheckedAt && tempPoolCheckedAt != nil {
			// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
			result.PoolCheckedAt = tempPoolCheckedAt
		}
		if jsonFieldDecodeErr != nil {
			return nil, jsonFieldDecodeErr
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)

	return results, nil
}

// FindPage reads a page of the Account rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *AccountRepository) FindPage(ctx context.Context, filter *AccountFilter, opts *AccountPageOptions) (*AccountPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Account rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = AccountSortById
	}
	column, ok := accountSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Account sorts by id, owner, name, vendor and rank, not %q", string(field))
	}
	byKey := field == AccountSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := accountFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, AccountAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "account")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`account.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, account.id) %s ((SELECT %s FROM account AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, account.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM account%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &AccountPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = accountPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *AccountRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM account WHERE account.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Account row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Account row through the behaviors' core (D103), in
// a transaction: each behavior's create initializes the fields it owns, and
// the row is read back. A refusal of the core's is returned as the
// *rules.Refusal it is.
func (r *AccountRepository) CreateOne(ctx context.Context, input *AccountCreate) (*types.Account, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Account, error) {
		return (&AccountRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// accountUniqueKeys are the conflict targets of Account's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var accountUniqueKeys = map[AccountUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	AccountUniqueById: {`(id)`, `id = account.id`, `SELECT "id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version" FROM account WHERE (id) IN (%s)`, ``, []string{`id`}},
}

// accountKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func accountKeyOf(on AccountUniqueKey, row *types.Account) (string, bool) {
	switch on {
	case AccountUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *AccountRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Account, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *AccountRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Account, error) {
	result := &types.Account{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempPoolAvailability sql.NullString
	var tempPoolOutUntil *types.TemporalDateTime
	var tempPoolOutReason sql.NullString
	var tempPoolCheckedAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Owner,

		&result.Name,

		&result.Vendor,

		&result.Kind,

		&result.Rank,

		&tempPoolAvailability,

		&tempPoolOutUntil,

		&tempPoolOutReason,

		&tempPoolCheckedAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempPoolAvailability.Valid {
		result.PoolAvailability = tempPoolAvailability.String
	}
	if tempPoolOutUntil != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PoolOutUntil = tempPoolOutUntil
	}
	if tempPoolOutReason.Valid {
		result.PoolOutReason = tempPoolOutReason.String
	}
	if tempPoolCheckedAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PoolCheckedAt = tempPoolCheckedAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, when the update sets no field or
// only if changed, and the second statement of an encrypted field.
func (r *AccountRepository) upsertRow(ctx context.Context, input *types.Account, on AccountUniqueKey, update *AccountUpdate, onlyIfChanged bool) (*UpsertResult[*types.Account], error) {
	key := accountUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := accountUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: owner
	fields = append(fields, `"owner"`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Owner.ToUUID())
	// Required field: name
	fields = append(fields, `"name"`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Name)
	// Required field: vendor
	fields = append(fields, `vendor`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Vendor)
	// Required field: kind
	fields = append(fields, `kind`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Kind)
	// Required field: rank
	fields = append(fields, `rank`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Rank)
	// Optional field: poolAvailability - only add if set
	{
		if !reflect.ValueOf(input.PoolAvailability).IsZero() {
			fields = append(fields, `pool_availability`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.PoolAvailability)
		}
	}
	// Optional field: poolOutUntil - only add if set
	{
		if input.PoolOutUntil != nil {
			fields = append(fields, `pool_out_until`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.PoolOutUntil))
		}
	}
	// Optional field: poolOutReason - only add if set
	{
		if !reflect.ValueOf(input.PoolOutReason).IsZero() {
			fields = append(fields, `pool_out_reason`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.PoolOutReason)
		}
	}
	// Optional field: poolCheckedAt - only add if set
	{
		if input.PoolCheckedAt != nil {
			fields = append(fields, `pool_checked_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.PoolCheckedAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Owner != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"owner" = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `account."owner"`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, (*update.Owner).ToUUID())
	}
	if update.Name != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"name" = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `account."name"`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Name)
	}
	if update.Vendor != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`vendor = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `account.vendor`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Vendor)
	}
	if update.Kind != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`kind = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `account.kind`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Kind)
	}
	if update.Rank != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`rank = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `account.rank`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Rank)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field compares none, so its WHERE is FALSE:
		// it leaves the row as it is, its version, stamps and history all,
		// and reads it back below.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO account (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || assigned == 0),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Account]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Account]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged && assigned > 0:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with, which the update sets no field of
		// or which already held the update's values, read back by its key:
		// a soft-deleted one is ErrNotFound.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Account row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.heldOfKey(ctx, on, keyValues, input)
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Account]{Row: found, Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// when update names no field or only if changed, and the second statement
// of each encrypted field.
func (r *AccountRepository) upsertBatches(ctx context.Context, inputs []*types.Account, on AccountUniqueKey, update AccountFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Account], error) {
	key := accountUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Owner {
		setClauses = append(setClauses, `"owner" = EXCLUDED."owner"`)
		compareCurrent = append(compareCurrent, `account."owner"`)
		compareNext = append(compareNext, `EXCLUDED."owner"`)
	}
	if update.Name {
		setClauses = append(setClauses, `"name" = EXCLUDED."name"`)
		compareCurrent = append(compareCurrent, `account."name"`)
		compareNext = append(compareNext, `EXCLUDED."name"`)
	}
	if update.Vendor {
		setClauses = append(setClauses, `vendor = EXCLUDED.vendor`)
		compareCurrent = append(compareCurrent, `account.vendor`)
		compareNext = append(compareNext, `EXCLUDED.vendor`)
	}
	if update.Kind {
		setClauses = append(setClauses, `kind = EXCLUDED.kind`)
		compareCurrent = append(compareCurrent, `account.kind`)
		compareNext = append(compareNext, `EXCLUDED.kind`)
	}
	if update.Rank {
		setClauses = append(setClauses, `rank = EXCLUDED.rank`)
		compareCurrent = append(compareCurrent, `account.rank`)
		compareNext = append(compareNext, `EXCLUDED.rank`)
	}

	results := make([]UpsertResult[*types.Account], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := accountUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: owner
			{
				cell := batchInsertCell{column: `"owner"`, set: true}
				cell.value = input.Owner.ToUUID()
				row = append(row, cell)
			}
			// Required field: name
			{
				cell := batchInsertCell{column: `"name"`, set: true}
				cell.value = input.Name
				row = append(row, cell)
			}
			// Required field: vendor
			{
				cell := batchInsertCell{column: `vendor`, set: true}
				cell.value = input.Vendor
				row = append(row, cell)
			}
			// Required field: kind
			{
				cell := batchInsertCell{column: `kind`, set: true}
				cell.value = input.Kind
				row = append(row, cell)
			}
			// Required field: rank
			{
				cell := batchInsertCell{column: `rank`, set: true}
				cell.value = input.Rank
				row = append(row, cell)
			}
			// Optional field: poolAvailability
			{
				cell := batchInsertCell{column: `pool_availability`}
				if !reflect.ValueOf(input.PoolAvailability).IsZero() {
					cell.value = input.PoolAvailability
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: poolOutUntil
			{
				cell := batchInsertCell{column: `pool_out_until`}
				if input.PoolOutUntil != nil {
					cell.value = time.Time(*input.PoolOutUntil)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: poolOutReason
			{
				cell := batchInsertCell{column: `pool_out_reason`}
				if !reflect.ValueOf(input.PoolOutReason).IsZero() {
					cell.value = input.PoolOutReason
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: poolCheckedAt
			{
				cell := batchInsertCell{column: `pool_checked_at`}
				if input.PoolCheckedAt != nil {
					cell.value = time.Time(*input.PoolCheckedAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field compares none, so its WHERE is
			// FALSE: it leaves each row as it is, its version, stamps and
			// history all, and reads it back below.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO account (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "owner", "name", "vendor", "kind", "rank", "pool_availability", "pool_out_until", "pool_out_reason", "pool_checked_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || len(setClauses) == 0),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = accountKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Account], len(prepared))
		for n, row := range returned {
			text, ok := accountKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Account wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Account]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, when update
		// names no field or only if changed, which it reads back by its key,
		// or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged && len(setClauses) > 0 {
				return nil, fmt.Errorf("the Account row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Account, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Account row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Account]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *AccountRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Account, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Account
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert left as they were, as one whose
// update sets no field or one only if changed does (D89). A key no live
// row holds is ErrNotFound.
func (r *AccountRepository) rowsOfKeys(ctx context.Context, on AccountUniqueKey, keys [][]any, inputs []*types.Account) ([]*types.Account, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(accountUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Account{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := accountKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Account, len(inputs))
	for i, input := range inputs {
		text, _ := accountKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Account row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// heldOfKey reads the row that holds input's value of the unique key on,
// keyValues the values of the key's columns its insert binds, which an
// upsert left as it was: by rowsOfKeys, or, for a key over an expression,
// whose columns read no row, by the expression's value over keyValues
// (sqlutil.UniqueKey.Held, D105). A key no live row holds is ErrNotFound.
func (r *AccountRepository) heldOfKey(ctx context.Context, on AccountUniqueKey, keyValues []any, input *types.Account) (*types.Account, error) {
	query := accountUniqueKeys[on].held
	if query == "" {
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Account{input})
		if err != nil {
			return nil, err
		}
		return found[0], nil
	}
	var read pgx.Row
	if r.tx != nil {
		read = r.tx.QueryRow(ctx, query, keyValues...)
	} else {
		read = r.db.pool.QueryRow(ctx, query, keyValues...)
	}
	row, err := r.scanReturned(read, nil)
	if err == pgx.ErrNoRows {
		return nil, fmt.Errorf("the Account row that holds the key %s is deleted: %w", string(on), ErrNotFound)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the row the upsert left: %w", err)
	}
	return row, nil
}

// CreateMany inserts multiple Account rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *AccountRepository) CreateMany(ctx context.Context, inputs []*AccountCreate) ([]*types.Account, error) {
	if len(inputs) == 0 {
		return []*types.Account{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Account, error) {
		repo := &AccountRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Account, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Account row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *AccountRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *AccountUpdate) (*types.Account, error) {
	if update == nil {
		update = &AccountUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Account, error) {
		repo := &AccountRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Account", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns}); err != nil {
			return nil, behaviorNotFound(err, "Account", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Account records matching the filter
func (r *AccountRepository) UpdateMany(ctx context.Context, filter *AccountFilter, update *AccountUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Owner != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"owner" = $%d`, paramNum))
		values = append(values, (*update.Owner).ToUUID())
	}
	if update.Name != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`"name" = $%d`, paramNum))
		values = append(values, *update.Name)
	}
	if update.Vendor != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`vendor = $%d`, paramNum))
		values = append(values, *update.Vendor)
	}
	if update.Kind != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`kind = $%d`, paramNum))
		values = append(values, *update.Kind)
	}
	if update.Rank != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`rank = $%d`, paramNum))
		values = append(values, *update.Rank)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE account SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Account row by ID through the
// behaviors' core (D103), in a transaction. It returns ErrNotFound when no
// live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *AccountRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Account", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Account", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Account records matching the filter
func (r *AccountRepository) DeleteMany(ctx context.Context, filter *AccountFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM account%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
